// Sovereign title fetch: the NAS fetches the page so the user's reading
// habits never leak to a third-party metadata service. http(s) only,
// bounded URL length, 10s timeout, title capped at 300 chars.
//
// 2026-06-12 SSRF hardening (review finding): the URL comes from whatever a
// user typed in a note, and the NAS sits on the family LAN + tailnet — so
// the fetch must never reach private/internal addresses. Blocklist covers
// loopback, RFC1918, link-local, CGNAT (Tailscale 100.64/10), .local/.ts.net
// and bare hostnames. Redirects are NOT followed (a public URL could 302
// into http://localhost), and the download is size-capped.
const decode = (s) => s.replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, (m, n) => String.fromCharCode(parseInt(n, 10)));
const isPrivateHost = (host) => {
  const h = String(host || '').toLowerCase().replace(/^\[|\]$/g, '');
  if (!h || h === 'localhost' || h.endsWith('.local') || h.endsWith('.ts.net') || h.endsWith('.internal')) return true;
  if (!h.includes('.')) return true; // bare intranet hostname
  if (/^127\./.test(h) || h === '0.0.0.0' || h === '::1' || h.startsWith('fe80:') || h.startsWith('fc') || h.startsWith('fd')) return true;
  if (/^10\./.test(h) || /^192\.168\./.test(h) || /^169\.254\./.test(h)) return true;
  if (/^172\.(1[6-9]|2\d|3[01])\./.test(h)) return true;
  if (/^100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\./.test(h)) return true; // CGNAT 100.64.0.0/10
  return false;
};
const out = [];
for (const item of items) {
  const q = item.json.query || {};
  let url = String(q.url || '');
  let title = '';
  let host = '';
  try { host = new URL(url).hostname; } catch (e) { url = ''; }
  if (url && /^https?:\/\//i.test(url) && url.length < 2048 && !isPrivateHost(host)) {
    try {
      const html = String(await this.helpers.httpRequest({ url, timeout: 10000, maxRedirects: 0, maxContentLength: 524288, headers: { 'user-agent': 'Mozilla/5.0 (PoeTech link-title)' } }));
      const og = html.match(/property=[\"']og:title[\"'][^>]*content=[\"']([^\"']{1,300})/i) || html.match(/content=[\"']([^\"']{1,300})[\"'][^>]*property=[\"']og:title/i);
      const t = html.match(/<title[^>]*>([^<]{1,300})/i);
      title = decode(((og && og[1]) || (t && t[1]) || '').replace(/\s+/g, ' ').trim());
    } catch (e) { /* unreachable, redirecting, or oversized page: empty title, never error */ }
  } else { url = ''; }
  out.push({ json: { url, title } });
}
return out;
